const closers=new Set();
const motionOff=()=>matchMedia('(prefers-reduced-motion:reduce)').matches||document.body.classList.contains('no-effects');
function upgrade(){document.querySelectorAll('select:not([data-enhanced])').forEach(select=>{
select.dataset.enhanced='true';select.hidden=true;const wrap=document.createElement('span');wrap.className='select-control';const trigger=document.createElement('button');trigger.type='button';trigger.className='select-trigger';trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-label',select.getAttribute('aria-label')||select.closest('label')?.childNodes[0]?.textContent||'選擇');const menu=document.createElement('span');menu.className='select-options';menu.setAttribute('role','listbox');menu.hidden=true;let animation,open=false;
const sync=()=>{trigger.disabled=select.disabled;trigger.textContent=(select.selectedOptions[0]?.textContent||'選擇')+' ⌄';menu.querySelectorAll('button').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.value===select.value)));};
const shape=()=>menu.dataset.direction==='up'?'inset(100% 0 0 0 round 12px)':'inset(0 0 100% 0 round 12px)';
const close=()=>{if(!open)return;open=false;trigger.setAttribute('aria-expanded','false');menu.inert=true;animation?.cancel();if(motionOff()){menu.hidden=true;return;}animation=menu.animate([{clipPath:'inset(0 0 0 0 round 12px)',opacity:1},{clipPath:shape(),opacity:0}],{duration:170,easing:'cubic-bezier(.4,0,.8,1)',fill:'both'});animation.onfinish=()=>{if(!open){menu.hidden=true;animation.cancel();}};};closers.add(close);
[...select.options].forEach(option=>{const b=document.createElement('button');b.type='button';b.textContent=option.textContent;b.dataset.value=option.value;b.setAttribute('role','option');b.onclick=()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));sync();close();trigger.focus();};menu.append(b);});
trigger.onclick=()=>{if(open){close();return;}for(const fn of closers)fn();open=true;animation?.cancel();menu.hidden=false;menu.inert=false;sync();const box=trigger.getBoundingClientRect(),needed=Math.min(menu.scrollHeight,240)+12;const direction=innerHeight-box.bottom<needed&&box.top>innerHeight-box.bottom?'up':'down';menu.dataset.direction=direction;menu.style.top=direction==='down'?'calc(100% + 6px)':'auto';menu.style.bottom=direction==='up'?'calc(100% + 6px)':'auto';trigger.setAttribute('aria-expanded','true');if(!motionOff())animation=menu.animate([{clipPath:shape(),opacity:0},{clipPath:'inset(0 0 0 0 round 12px)',opacity:1}],{duration:280,easing:'cubic-bezier(.16,1,.3,1)'});menu.querySelector('[aria-selected=true]')?.focus({preventScroll:true});};
wrap.onkeydown=e=>{const options=[...menu.children];if(e.key==='Escape'){close();trigger.focus();e.stopPropagation();}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();if(!open){trigger.click();return;}let i=options.indexOf(document.activeElement);i=e.key==='Home'?0:e.key==='End'?options.length-1:(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options[i]?.focus();}};
select.addEventListener('change',sync);select.after(wrap);wrap.append(trigger,menu);sync();const cleanup=new MutationObserver(()=>{if(!wrap.isConnected){closers.delete(close);animation?.cancel();cleanup.disconnect();}});cleanup.observe(document.documentElement,{childList:true,subtree:true});});}
new MutationObserver(upgrade).observe(document.documentElement,{childList:true,subtree:true});document.addEventListener('click',e=>{if(!e.target.closest('.select-control'))for(const close of closers)close();});upgrade();
